def transform(grid):
    H, W = len(grid), len(grid[0])
    # Locate the rectangular color key: each column (vertical key) or row
    # (horizontal key) is a uniform run, with key colors in reading order.
    key = None
    for r0 in range(H):
        for c0 in range(W):
            for hh in range(1, H-r0+1):
                for ww in range(1, W-c0+1):
                    if hh == 1 and ww == 1:
                        continue
                    cells = [grid[r][c] for r in range(r0,r0+hh) for c in range(c0,c0+ww)]
                    if not all(cells):
                        continue
                    # A key is a rectangular strip whose columns or rows are
                    # individually constant, regardless of its aspect ratio.
                    if all(len({grid[r][c] for r in range(r0,r0+hh)}) == 1 for c in range(c0,c0+ww)):
                        colors = [grid[r0][c] for c in range(c0,c0+ww)]
                        if hh >= 2 and len(set(colors)) > 1:
                            cand=(hh*ww,r0,c0,hh,ww,colors)
                            if key is None or cand[0] > key[0]: key=cand
                    if all(len({grid[r][c] for c in range(c0,c0+ww)}) == 1 for r in range(r0,r0+hh)):
                        colors = [grid[r][c0] for r in range(r0,r0+hh)]
                        if ww >= 2 and len(set(colors)) > 1:
                            cand=(hh*ww,r0,c0,hh,ww,colors)
                            if key is None or cand[0] > key[0]: key=cand
    if key is None:
        return [row[:] for row in grid]
    _, kr, kc, kh, kw, palette = key
    # Recover the repeated motif from the existing colored copies.
    by_color = {}
    for r in range(H):
        for c in range(W):
            v=grid[r][c]
            if v and not (kr <= r < kr+kh and kc <= c < kc+kw):
                by_color.setdefault(v, []).append((r,c))
    candidates=[]
    for color, pts in by_color.items():
        rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        mask={(r-r0,c-c0) for r,c in pts}
        candidates.append((len(mask),color,r0,c0,r1-r0+1,c1-c0+1,mask))
    if not candidates:
        return [row[:] for row in grid]
    _, anchor_color, ar, ac, mh, mw, motif = max(candidates)
    # Arrange every palette color as a vertically stacked copy, centered in
    # the canvas; the seed's original position is only a clue to the motif.
    top = (H - len(palette)*mh) // 2
    out=[[0]*W for _ in range(H)]
    for i,color in enumerate(palette):
        y=top+i*mh
        for dr,dc in motif:
            if 0 <= y+dr < H and 0 <= ac+dc < W:
                out[y+dr][ac+dc]=color
    return out

